  void ClearGovernance(){C<DataGrid>("GovTasksGrid").ItemsSource=null;C<ListBox>("GovEvidenceList").ItemsSource=null;C<TextBlock>("GovResultText").Text="普通文字审批保持原规则；工程治理按风险分级。";C<TextBlock>("MaterialsReceiptsText").Text="未发生模拟材料接收；真实三方未交付。";}
  void RenderGovernance(object data){var attempts=Json.Arr(Json.Get(data,"exchangeAttempts"));C<TextBlock>("MaterialsReceiptsText").Text="模拟材料接收："+(attempts.Length==0?"暂无":String.Join("；",attempts.Select(a=>Name(Json.Str(a,"role"))+" / v"+Json.Str(a,"version")+"："+(Json.Str(a,"state")=="CONFIRMED"?"模拟字节已校验":Json.Str(a,"state")))))+"。真实Agent未接收。";foreach(var h in Json.Arr(Json.Get(data,"manualHandovers")))C<TextBlock>("MaterialsReceiptsText").Text+="\n人工交付："+Name(Json.Str(h,"role"))+" / v"+Json.Str(h,"version")+" · "+Json.Str(h,"state")+"（平台未核验）";var gov=Json.Get(data,"governance");var grid=C<DataGrid>("GovTasksGrid");string selected=grid.SelectedItem is GovTaskRow?((GovTaskRow)grid.SelectedItem).Id:null;var rows=Json.Arr(Json.Get(gov,"tasks")).Select(t=>new GovTaskRow(){Id=Json.Str(t,"id"),Title=Json.Str(t,"title"),Owner=Name(Json.Str(t,"ownerId")),Risk=Json.Str(t,"riskLevel"),Reviewers=String.Join("、",Json.Arr(Json.Get(t,"reviewerIds")).Select(x=>Name(Convert.ToString(x)))),Rounds=Json.Arr(Json.Get(t,"rounds")).Length.ToString(),Raw=t}).ToArray();grid.ItemsSource=rows;grid.SelectedItem=rows.FirstOrDefault(t=>t.Id==selected)??rows.FirstOrDefault();var evidence=new List<GovEvidenceRow>();foreach(var e in Json.Arr(Json.Get(data,"reviewEvidence"))){evidence.Add(new GovEvidenceRow(){Heading=Name(Json.Str(e,"authorId"))+" · 材料 v"+Json.Str(e,"packageVersion")+" · "+(Json.Bool(e,"isCurrentPackageVersion")?"当前版本":"历史版本（不沿用批准）"),Body=Json.Str(e,"body"),Source="来源："+(Json.Bool(e,"simulation")?"用户登记的模拟意见":"用户登记的未核实陈述")+" · "+Json.Str(e,"verdict")+" · 引用 "+Json.Arr(Json.Get(e,"references")).Length+" 项；不代表真实Agent复核或实施授权。"});}foreach(var ev in Json.Arr(Json.Get(gov,"events"))){if(Json.Str(ev,"type")!="governance.reminder")continue;evidence.Add(new GovEvidenceRow(){Heading="治理提醒 · "+Json.Str(ev,"code"),Body="请求："+Json.Str(ev,"request")+"\n规则："+Json.Str(ev,"rule")+"\n影响："+Json.Str(ev,"impact")+"\n替代："+Json.Str(ev,"alternative"),Source="MAG-001 · 结构化请求核对；不宣称能够理解所有自然语言意图。"});}C<ListB