  async Task ReceiveMockMaterials(){var row=SelectedMaterial();string[] recipients=Chosen();if(recipients.Length==0)throw new InvalidOperationException("先在上方明确选择模拟接收者。");var dialog=Dialog("仅分发至选中的模拟接收对象",650,280);var panel=new StackPanel(){Margin=new Thickness(20)};panel.Children.Add(new TextBlock(){Text="本次对象："+String.Join("、",recipients.Select(Name))+"。仅复制材料到平台自有模拟收件箱并读取校验，不调用原生Agent、附件窗口或真实会话。暂停的模拟对象不会接收。",TextWrapping=TextWrapping.Wrap});Accept(dialog,panel,"确认本次模拟分发");dialog.Content=panel;int epoch=Epoch;if(dialog.ShowDialog()!=true)return;var attempts=Json.Arr(await Post("materials-queue","packageId",row.Id,"version",Convert.ToInt32(row.Version),"recipients",recipients));foreach(var a in attempts)await Post("materials-receive","attemptId",Json.Str(a,"id"));if(epoch!=Epoch)return;await RefreshMaterials();MaterialsNote("本次模拟分发已处理；请查看接收状态。真实Agent未收到材料。");}
  async Task RegisterGovernance(){RequireMaterials();var registered=Json.Arr(Json.Get(Json.Get(MaterialsState,"governance"),"tasks"));var tasks=Json.Arr(Json.Get(MaterialsState,"tasks")).Where(t=>!registered.Any(g=>Json.Str(g,"id")==Json.Str(t,"id"))).ToArray();if(tasks.Length==0)throw new InvalidOperationException("没有未登记的文字任务，请先在任务页创建。");var d=Dialog("冻结工程任务范围与必要复核",740,780);var p=new StackPanel(){Margin=new Thickness(20)};p.Children.Add(new TextBlock(){Text="当前仅管理虚构工程，不授予文件写入/命令执行权限。负责人沿用任务执行者。",TextWrapping=TextWrapping.Wrap});var task=new ComboBox(){ItemsSource=tasks.Select(t=>Json.Str(t,"title")+" · "+Name(Json.Str(t,"ownerId"))).ToArray(),SelectedIndex=0};p.Children.Add(task);p.Children.Add(new TextBlock(){Text="风险等级（按实际影响判断）",Margin=new Thickness(0,12,0,5)});var risk=new ComboBox(){ItemsSource=new string[]{"L0","L1","L2","L3"},SelectedIndex=1};p.Children.Add(risk);var basis=Field(p,"分级依据","仅当前虚构材料的可逆协调与核验",2);var goal=Field(p,"任务目标（冻结后新增需求另建任务）","核对当前虚构材料的版本与完整性",2);var scope=Field(p,"范围","仅当前任务材料与模拟接收，不执行源代码",2);var criteria=Field(p,"验收标准，每行一条","材料字节完整，接收状态如实记录",2);var checks=new List<CheckBox>();p.Children.Add(new TextBlock(){Text="必要独立复核者：L0不选；L1一名；L2/L3第三方按依据介入。",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,12,0,5)});foreach(string role in new string[]{"hermes","deepseek","chatgpt"}){var c=new CheckBox(){Content=Name(role),Tag=role,IsChecked=role=="deepseek"&&Json.Str(tasks[0],"ownerId")!="deepseek",Foreground=System.Windows.Media.Brushes.White};checks.Add(c);p.Children.Add(c);}var escalationKinds=new string[]{"unresolved_substantive_disagreement","cross_domain","important_security_or_architecture_risk","clear_additional_value"};var escalation=new ComboBox(){ItemsSource=new string[]{"实质性分歧未解决","跨专业领域","重要安全或架构风险","第三方有明确额外价值"},SelectedIndex=0};p.Children.Add(new TextBlock(){Text="如需第二名审查者：介入依据",Margin=new Thickness(0,10,0,4)});p.Children.Add(escalation);var escalationReason=Field(p,"第二名审查者的必要性（可留空）","",2);var escalationEvidence=Field(p,"相关证据记录，每行