  async Task StartGovernanceReview(){var t=SelectedGovernedTask();var pkg=SelectedMaterial();int epoch=Epoch;object basis=null;if(Json.Arr(Json.Get(t.Raw,"rounds")).Length>=2){var reason=Prompt("超过两轮需要明确新依据","本操作只支持当前材料有实质变化的复核；后台核对新快照。填写变化及必要性：","");if(String.IsNullOrWhiteSpace(reason))return;basis=Json.D("kind","substantive_code_change","reason",reason);}var result=await Post("materials-governance-review","taskId",t.Id,"packageId",pkg.Id,"version",Convert.ToInt32(pkg.Version),"reopenBasis",basis);if(epoch!=Epoch)return;await RefreshMaterials();ShowGovernanceResult(result);}
  async Task RecordGovernanceOpinion(){var pkg=SelectedMaterial();var attempts=Json.Arr(Json.Get(MaterialsState,"exchangeAttempts")).Where(a=>Json.Str(a,"package_id")==pkg.Id&&Json.Str(a,"version")==pkg.Version&&Json.Str(a,"state")=="CONFIRMED").ToArray();if(attempts.Length==0)throw new InvalidOperationException("先向选中的模拟对象分发本版材料并确认模拟字节接收。");var files=Json.Arr(Json.Get(await Post("materials-file-list","packageId",pkg.Id,"version",Convert.ToInt32(pkg.Version)),"files"));var d=Dialog("登记原始意见及版本证据",760,720);var p=new StackPanel(){Margin=new Thickness(20)};p.Children.Add(new TextBlock(){Text="意见原文不改写。本次是用户登记的模拟意见，不冒充真实Agent的判断。",TextWrapping=TextWrapping.Wrap});var author=new ComboBox(){ItemsSource=attempts.Select(a=>Name(Json.Str(a,"role"))+" · 模拟回执已确认").ToArray(),SelectedIndex=0};p.Children.Add(author);var body=Field(p,"意见原文","虚构意见：已核对本版材料，保留独立表达。",6);var verdict=new ComboBox(){ItemsSource=new string[]{"COMMENT","PASS","CHANGES_REQUESTED","REJECT","UNDETERMINED"},SelectedIndex=0};p.Children.Add(verdict);p.Children.Add(new TextBlock(){Text="引用包内文件（可选；不手填哈希）",Margin=new Thickness(0,12,0,5)});var file=new ComboBox(){ItemsSource=(new string[]{"不引用文件"}).Concat(files.Select(f=>Json.Str(f,"path"))).ToArray(),SelectedIndex=files.Length>0?1:0};p.Children.Add(file);var governed=C<DataGrid>("GovTasksGrid").SelectedItem as GovTaskRow;var issues=governed==null?new object[0]:Json.Arr(Json.Get(governed.Raw,"issues"));p.Children.Add(new TextBlock(){Text="针对哪个Issue（修复验证必须选择）",Margin=new Thickness(0,12,0,5)});var relatedIssue=new ComboBox(){ItemsSource=(new string[]{"普通版本意见，不针对Issue"}).Concat(issues.Select(i=>Json.Str(i,"problemKey"))).ToArray(),SelectedIndex=0};p.Children.Add(relatedIssue);var outcome=new ComboBox(){ItemsSource=new string[]{"UNDETERMINED","PASSED","FAILED"},SelectedIndex=0,Margin=new Thickness(0,12,0,5)};p.Children.Add(new TextBlock(){Text="该Issue的验证结论；与上方PASS及包内文件证据共同核对"});p.Children.Add(outcome);var start=Field(p,"起始行（可留空）","",1);var end=Field(p,"结束行（填写起始行时必填）","",1);Accept(d,p,"保存原意见与版本证据");d.Content=new ScrollViewer(){Content=p,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};int epoch=Epoch;if(d.ShowDialog()!=true)return;var refs=new List<object>();if(file.SelectedIndex>0){var f=files[file.SelectedIndex-1];var reference=Json.D("type",Json.Str(f,"source_type"),"filePath",Json.Str(f,"path"));if(!String.IsNullOrWhiteSpace(start.Text)){reference["lineStart"]=Int32.Parse(start.Text);reference["lineEnd"]=Int32.Parse(end.Text);}refs.Add(reference);}var selectedAttempt=attempts[author.SelectedIndex];await Post("materials-review-evidence","packageId",pkg.Id,"version",Convert.ToInt32(pkg.Version),"authorId",Json.Str(selectedAttempt,"role"),"attemptId",Json.Str(selectedAttempt,"id"),"body",body.Text,"verdict",Convert.ToString(verdict.SelectedItem),"references",refs.ToArray(),"relatedIssueIds",relatedIssue.SelectedIndex==0?new string[0]:new string[]{Json.Str(issues[relatedIssue.SelectedIndex-1],"id")},"verificationOutcome",Convert.ToString(outcome.SelectedItem));if(epoch!=Epoch)return;await RefreshMaterials();C<TextBlock>("GovResultText").Text="意见原文与本版材料证据已保留；不是实施授权。";}
  async Task CreateGovernanceIssue(){var t=SelectedGovernedTask();var d=Dialog("登记唯一问题",650,430);var p=new StackPanel(){Margin=new Thickness(20)};var key=Field(p,"问题标识（同任务相同标识沿用原Issue，不重复创建）","fictional-style-choice",1);var severity=new ComboBox(){ItemsSource=new string[]{"P0","P1","P2","P3"},SelectedIndex=2};p.Children.Add(severity);p.Children.Add(new TextBlock(){Text="P0/P1阻断；P2/P3保留改进记录。严重程度应依据影响，不用标签掩盖风险。",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,12,0,5)});Accept(d,p,"登记问题");d.Content=p;int epoch=Epoch;if(d.ShowDialog()!=true)return;await Post("materials-governance-issue","taskId",t.Id,"operation","create","problemKey",key.Text,"severity",Convert.ToString(severity.SelectedItem));if(epoch!=Epoch)return;await RefreshMaterials();C<TextBlock>("GovResultText").Text="问题已登记，非阻断建议不会自动阻止交付。";}
  async Task TransitionGovernanceIssue(){var t=SelectedGovernedTask();var issues=Json.Arr(Json.Get(t.Raw,"issues"));if(issues.Length==0)throw new InvalidOperationException("当前任务暂无问题。");var d=Dialog("处理既有Issue",740,640);var p=new StackPanel(){Margin=new Thickness(20)};var issue=new ComboBox(){ItemsSource=issues.Select(i=>Json.Str(i,"problemKey")+" · "+Json.Str(i,"severity")+" · "+Json.Str(i,"state")).ToArray(),SelectedIndex=0};p.Children.Add(issue);var to=new ComboBox(){ItemsSource=new string[]{"ACKNOWLEDGED","IN_PROGRESS","FIXED","VERIFIED","DEFERRED","REJECTED","CLOSED","OPEN","重评P0","重评P1","重评P2","重评P3"},SelectedIndex=1,Margin=new Thickness(0,12,0,10)};p.Children.Add(to);var reason=Field(p,"处理依据","",3);var basis=new ComboBox(){ItemsSource=new string[]{"无重开/拒绝依据","new_evidence","substantive_code_change","risk_change"},SelectedIndex=0};p.Children.Add(basis);var evidence=Field(p,"依据记录ID，每行一项（拒绝/重开必须提供）","",2);var opinions=Json.Arr(Json.Get(MaterialsState,"reviewEvidence")).Where(e=>Json.Str(e,"taskId")==t.Id).ToArray();var verifier=new ComboBox(){ItemsSource=(new string[]{"无独立验证记录"}).Concat(opinions.Select(e=>Name(Json.Str(e,"authorId"))+" · v"+Json.Str(e,"packageVersion")+" · "+(Json.Str(e,"body").Length>45?Json.Str(e,"body").Substring(0,45):Json.Str(e,"body")))).ToArray(),SelectedIndex=0};p.Children.Add(verifier);Accept(d,p,"提交状态变更");d.Content=new ScrollViewer(){Content=p};int epoch=Epoch;if(d.ShowDialog()!=true)return;object verification=verifier.SelectedIndex>0?opinions[verifier.SelectedIndex-1]:null;var refs=Lines(evidence.Text).Concat(verification==null?new string[0]:new string[]{Json.Str(verification,"id")}).Distinct().ToArray();string target=Convert.ToString(to.SelectedItem);if(target=="OPEN"&&Convert.ToString(basis.SelectedItem)=="substantive_code_change"){var selected=SelectedMaterial();refs=new string[]{"artifact:"+selected.Id+":"+selected.Version};}var result=await Post("materials-governance-issue","taskId",t.Id,"issueId",Json.Str(issues[issue.SelectedIndex],"id"),"operation",to.SelectedIndex>=8?"reclassify":"transition","to",target,"severity",to.SelectedIndex>=8?"P"+(to.SelectedIndex-8):null,"reason",reason.Text,"basis",basis.SelectedIndex==0&&to.SelectedIndex<8?null:Json.D("kind",to.SelectedIndex>=8?"risk_change":Convert.ToString(basis.SelectedItem),"reason",reason.Text,"evidenceRefs",refs),"verifierId",verification==null?null:Json.Str(verification,"authorId"),"verificationRef",verification==null?null:Json.Str(verification,"id"));if(epoch!=Epoch)return;await RefreshMaterials();ShowGovernanceResult(result);}
  async Task CheckGovernanceDelivery(){var task=SelectedGovernedTask();var pkg=SelectedMaterial();var d=Dialog("检查模拟材料流程交付条件",670,350);var p=new StackPanel(){Margin=new Thickness(20)};p.Children.Add(new TextBlock(){Text="此操作校验封存包字节和模拟流程记录，不运行工程代码，不把导入测试报告当作实际执行证据，也不授予真实项目实施权限。",TextWrapping=TextWrapping.Wrap});var accepted=new CheckBox(){Content="我已核对本次模拟材料流程的冻结验收条件",IsChecked=String.IsNullOrEmpty(SelfTest)?false:true,Foreground=System.Windows.Media.Brushes.White,Margin=new Thickness(0,20,0,5)};p.Children.Add(accepted);Accept(d,p,"检查并保留结果");d.Content=p;int epoch=Epoch;if(d.ShowDialog()!=true)return;if(accepted.IsChecked==true)await Post("materials-mock-self-test","taskId",task.Id,"packageId",pkg.Id,"version",Convert.ToInt32(pkg.Version));var result=await Post("materials-governance-assess","taskId",task.Id,"operation","delivery","packageId",pkg.Id,"version",Convert.ToInt32(pkg.Version),"acceptanceSatisfied",accepted.IsChecked==true);if(epoch!=Epoch)return;await RefreshMaterials();ShowGovernanceResult(result);GovernanceProof=Json.D("passed",!Json.Bool(result,"blocked"),"simulation",true,"realIndependentReview",false,"executionAuthorized",Json.Bool(result,"executionAuthorized"));}
  async Task CheckGovernanceIntent(){var t=SelectedGovernedTask();var d=Dialog("核对明确治理请求",690,350);var p=new StackPanel(){Margin=new Thickness(20)};var operations=new string[]{"force_all_agents_every_task","rereview_passed_task","replace_for_elegance","add_current_acceptance","reopen_closed_issue","ordinary_task_modify_governance"};var options=new ComboBox(){ItemsSource=new string[]{"所有任务都三方审查","无新依据重审已通过任务","仅为更优雅而重新选型","增加当前任务验收","无新依据重开问题","普通任务修改治理制度"},SelectedIndex=0};p.Children.Add(options);p.Children.Add(new TextBlock(){Text="这是明确结构化请求的规则核对，不用关键词猜测所有自然语言。",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,15,0,5)});Accept(d,p,"查看条款与替代方案");d.Content=p;int epoch=Epoch;if(d.ShowDialog()!=true)return;var result=await Post("materials-governance-assess","taskId",t.Id,"operation","intent","intent",Json.D("operation",operations[options.SelectedIndex],"requestSummary",Convert.ToString(options.SelectedItem)));if(epoch!=Epoch)return;await RefreshMaterials();ShowGovernanceResult(result);}
  async Task RunGovernanceSelfTest(){MainTabs().SelectedIndex=3;while(MaterialsBusy)await Task.Delay(20);await MaterialsAction(RefreshMaterials);await MaterialsAction(RegisterGovernance);await MaterialsAction(StartGovernanceReview);Suppress=true;foreach(ListBoxItem item in Receivers.Items)item.IsSelected=Convert.ToString(item.Tag)=="deepseek";Suppress=false;await Post("configure","recipients",new string[]{"deepseek"});await MaterialsAction(ReceiveMockMaterials);await MaterialsAction(RecordGovernanceOpinion);await MaterialsAction(CreateGovernanceIssue);await MaterialsAction(CheckGovernanceDelivery);if(GovernanceProof==null||!Json.Bool(GovernanceProof,"passed"))throw new Exception("Native governance workflow failed");await MaterialsAction(CheckGovernanceIntent);}
